from pathlib import Path
import json,base64,zipfile,xml.etree.ElementTree as ET,io
from PIL import Image
import numpy as np
R=Path(__file__).resolve().parents[2];O=R/'renders/entrees_six_donjons_v1/sakura_validee';m=json.loads((O/'manifest.json').read_text());names=m['layers']
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
labels=['Sol et chemin','Ombres portées','Végétation basse et pétales','Profondeur du passage','Arbres de la lisière','Arbre central','Arbre avant gauche']
images={n:data(O/(n+'.png')) for n in names};extra={'atlas':data(O/'SAKURA_ARBRES_tilesheet_8px.png'),'clean':data(O/'SOL_PROPRE_alternative.png')}
# Editable OpenRaster with true aligned layers and standard source-over compositing.
root=ET.Element('image',{'w':str(m['size'][0]),'h':str(m['size'][1]),'name':'Entrée Sakura A validée'});stack=ET.SubElement(root,'stack')
for i in reversed(range(len(names))):ET.SubElement(stack,'layer',{'name':labels[i],'src':f'data/layer{i}.png','opacity':'1.0','visibility':'visible','composite-op':'svg:src-over','x':'0','y':'0'})
with zipfile.ZipFile(O/'SAKURA_ENTREE_A_multicalques.ora','w') as z:
 z.writestr('mimetype','image/openraster',compress_type=zipfile.ZIP_STORED);z.writestr('stack.xml',ET.tostring(root,encoding='utf-8',xml_declaration=True));z.write(O/'composition_identique.png','mergedimage.png')
 for i,n in enumerate(names):z.write(O/(n+'.png'),f'data/layer{i}.png')
 thumb=Image.open(O/'composition_identique.png');thumb.thumbnail((256,256));b=io.BytesIO();thumb.save(b,format='PNG');z.writestr('Thumbnails/thumbnail.png',b.getvalue())
# Unique resource names avoid overwriting other imported PNG tilesets.
pmd=O/'import_png';pmd.mkdir(exist_ok=True)
for n in names:
 pmd.joinpath('SAKURA_ENTREE_A_'+n+'.png').write_bytes((O/(n+'.png')).read_bytes())
pmd.joinpath('SAKURA_ARBRES_tilesheet_8px.png').write_bytes((O/'SAKURA_ARBRES_tilesheet_8px.png').read_bytes())
# Verify both sprite coordinates and exact composition, not just matching dimensions.
a=np.array(Image.open(O/'composition_identique.png').convert('RGBA'));comp=Image.new('RGBA',tuple(m['size']))
for n in names:comp.alpha_composite(Image.open(O/(n+'.png')).convert('RGBA'))
assert np.array_equal(np.array(comp),a)
atlas=Image.open(O/'SAKURA_ARBRES_tilesheet_8px.png').convert('RGBA')
for sprite in m['trees_tilesheet']['sprites']:
 exported=Image.open(O/(sprite['name']+'_sprite.png')).convert('RGBA');assert np.array_equal(np.array(exported),np.array(atlas.crop(sprite['atlas_box'])))
(O/'verification.json').write_text(json.dumps({'layers':7,'size':m['size'],'source_composition_pixel_identical':True,'isolated_tree_sprites':2,'atlas_copies_exact':True,'ora_contains_7_aligned_layers':True,'runtime_validated':False},indent=2))
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sakura · entrée validée en calques</title><style>*{box-sizing:border-box}body{margin:0;background:#211c26;color:#f6e4ed;font:16px system-ui}header,main,footer{max-width:1360px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{line-height:1.6;color:#d5bdcc}.tag{color:#edb4cc;font-size:12px;letter-spacing:2px}.bar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}button{padding:11px;border:1px solid #886577;background:#533c4e;color:white;border-radius:6px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}canvas{width:100%;image-rendering:pixelated;background:repeating-conic-gradient(#343438 0% 25%,#2d2f32 0% 50%) 50%/16px 16px}aside{background:#302632;padding:18px;border-radius:8px}label{display:block;margin:16px 0;font-size:14px}a{color:#ffc7dc}small{color:#cbbccc}footer{border-top:1px solid #614659}@media(max-width:780px){.grid{grid-template-columns:1fr}}</style><header><div class="tag">ENTRÉE SAKURA A / LAYOUT VALIDÉ CONSERVÉ</div><h1>Sol · végétation · arbres · ombres</h1><p>Sept calques alignés. Avec tous les calques activés, la composition est identique pixel par pixel à l’image validée. Deux arbres isolés sont également disponibles en sprites et sur une feuille transparente.</p></header><main><div class="bar"><button onclick="preset('all')">Composition validée</button><button onclick="preset('floor')">Sol seul</button><button onclick="preset('trees')">Arbres seuls</button><button onclick="preset('shadow')">Ombres seules</button><button id="atlas">Feuille d’arbres</button><button id="save">Télécharger la vue PNG</button></div><div class="grid"><section><canvas id="view" width="1200" height="896"></canvas><p id="status">1200 ×896 · aucune modification du layout validé</p></section><aside><b>Calques PNG</b><div id="layers"></div><label><input type="checkbox" id="clean">Sol entièrement reconstitué (alternative)</label><small>Par défaut, les pixels du sol restés visibles sont conservés. L’alternative fournit une base entièrement dégagée, mais change ces pixels de sol.</small><p><a id="atlasDownload">Télécharger le tilesheet d’arbres</a></p></aside></div></main><footer><p>Fichier éditable : SAKURA_ENTREE_A_multicalques.ora. Feuille d’arbres :416×216, grille8px. PNG d’import à noms uniques fournis dans le pack.</p><small>Illustration générée puis découpée et corrigée, pas des sprites canoniques récupérés ni un dessin attribué à un artiste humain. Les ombres peintes sont liées à leurs positions et au sol de cette scène. La lisière contient des arbres partiellement occultés ; seuls les deux arbres isolés sont exportés comme sprites complets visibles. Pas de validation PMDO.</small></footer><script>const DATA=__DATA__,EXTRA=__EXTRA__,LABELS=__LABELS__,names=Object.keys(DATA),images={},on={},checks={},c=document.getElementById('view'),ctx=c.getContext('2d');let atlas=false,clean=false;function im(src){const i=new Image();i.src=src;return i}const extra={atlas:im(EXTRA.atlas),clean:im(EXTRA.clean)};function save(src,name){const a=document.createElement('a');a.href=src;a.download=name;a.click()}for(let j=0;j<names.length;j++){const n=names[j];images[n]=im(DATA[n]);on[n]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;checks[n]=ch;ch.onchange=()=>{atlas=false;on[n]=ch.checked};a.href=DATA[n];a.download='SAKURA_ENTREE_A_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(LABELS[j]),a);document.getElementById('layers').append(l)}function preset(mode){atlas=false;clean=false;document.getElementById('clean').checked=false;for(let i=0;i<names.length;i++){const n=names[i];on[n]=mode==='all'||mode==='floor'&&i===0||mode==='trees'&&i>=4||mode==='shadow'&&i===1;checks[n].checked=on[n]}}document.getElementById('atlas').onclick=()=>atlas=!atlas;document.getElementById('clean').onchange=e=>clean=e.target.checked;document.getElementById('save').onclick=()=>save(c.toDataURL(),atlas?'SAKURA_ARBRES_tilesheet_8px.png':'SAKURA_ENTREE_A_composition.png');const ad=document.getElementById('atlasDownload');ad.href=EXTRA.atlas;ad.download='SAKURA_ARBRES_tilesheet_8px.png';function draw(i){if(i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}function render(){let w=atlas?416:1200,h=atlas?216:896;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,w,h);if(atlas)draw(extra.atlas);else for(let i=0;i<names.length;i++)if(on[names[i]])draw(i===0&&clean?extra.clean:images[names[i]]);document.getElementById('status').textContent=atlas?'Deux sprites visibles complets ·416×216 · grille8px':clean?'Sol alternatif reconstitué · placement des objets inchangé':'1200×896 · composition originale exacte lorsque les sept calques sont actifs';requestAnimationFrame(render)}requestAnimationFrame(render);</script></html>'''
(R/'apercu_sakura_entree_calques_v1.html').write_text(h.replace('__DATA__',json.dumps(images)).replace('__EXTRA__',json.dumps(extra)).replace('__LABELS__',json.dumps(labels)),encoding='utf8')
print('Editable ORA,unique import PNGs,viewer and verification saved')
